const raw = $input.first().json;
const body = raw.body || raw;

// Handle both webhook and Google Form formats
const isFormResponse = !!(body['Lead Name'] || body['Your Name']);

let fields = {};
if (isFormResponse) {
  fields = {
    leadName:        body['Lead Name']          || body['Your Name']   || null,
    leadEmail:       body['Email']              || body['Lead Email']  || null,
    leadPhone:       body['Phone']              || body['Lead Phone']  || null,
    propertyAddress: body['Property Address']                          || null,
    preferredDates:  body['Preferred Dates']    || body['Preferences'] || null,
    notes:           body['Additional Notes']   || body['Notes']       || null,
    source:          'Google Form'
  };
} else {
  fields = {
    leadName:        body.leadName        || body.name        || null,
    leadEmail:       body.leadEmail       || body.email       || null,
    leadPhone:       body.leadPhone       || body.phone       || null,
    propertyAddress: body.propertyAddress || body.address     || null,
    preferredDates:  body.preferredDates  || body.preferences || null,
    notes:           body.notes                               || null,
    source:          body.source          || 'Webhook'
  };
}

return [{
  json: {
    ...fields,
    recordId:  `view-${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

const config = $('Set: Agent Configuration').first().json;
const lead   = $('Normalize Request Details').first().json;

const daysAhead = parseInt(config.SLOT_DAYS_AHEAD || '7');
const duration  = parseInt(config.VIEWING_DURATION || '30');

const availabilityMap = {
  0: config.SUN_HOURS || '',
  1: config.MON_HOURS || '',
  2: config.TUE_HOURS || '',
  3: config.WED_HOURS || '',
  4: config.THU_HOURS || '',
  5: config.FRI_HOURS || '',
  6: config.SAT_HOURS || ''
};

const slots = [];
const now   = new Date();

for (let day = 1; day <= daysAhead && slots.length < 6; day++) {
  const date = new Date(now);
  date.setDate(now.getDate() + day);
  const dayOfWeek = date.getDay();
  const hours = availabilityMap[dayOfWeek];

  if (!hours || hours.trim() === '') continue;

  const [startStr, endStr] = hours.split('-');
  if (!startStr || !endStr) continue;

  const [startH, startM] = startStr.trim().split(':').map(Number);
  const [endH]           = endStr.trim().split(':').map(Number);

  // Three slots per day: start, midday, one hour before end
  const slotTimes = [
    { h: startH,                     m: startM },
    { h: Math.floor((startH + endH) / 2), m: 0 },
    { h: endH - 1,                   m: 0 }
  ];

  for (const t of slotTimes) {
    if (slots.length >= 6) break;

    const slotStart = new Date(date);
    slotStart.setHours(t.h, t.m, 0, 0);
    const slotEnd = new Date(slotStart);
    slotEnd.setMinutes(slotStart.getMinutes() + duration);

    if (slotStart > now) {
      slots.push({
        label:     slotStart.toLocaleDateString('en-US', {
                     weekday: 'long', month: 'long', day: 'numeric'
                   }) + ' at ' +
                   slotStart.toLocaleTimeString('en-US', {
                     hour: 'numeric', minute: '2-digit', hour12: true
                   }),
        startIso:  slotStart.toISOString(),
        endIso:    slotEnd.toISOString(),
        dateShort: slotStart.toLocaleDateString('en-US', {
                     weekday: 'short', month: 'short', day: 'numeric'
                   })
      });
    }
  }
}

const topSlots = slots.slice(0, 3);

return [{
  json: {
    ...lead,
    config,
    slots:      topSlots,
    slot1:      topSlots[0]?.label    || 'To be confirmed',
    slot2:      topSlots[1]?.label    || 'To be confirmed',
    slot3:      topSlots[2]?.label    || 'To be confirmed',
    slot1Start: topSlots[0]?.startIso || null,
    slot2Start: topSlots[1]?.startIso || null,
    slot3Start: topSlots[2]?.startIso || null,
    calendlyUrl: `https://calendly.com/${config.CALENDLY_USERNAME}/${config.CALENDLY_EVENT_SLUG}`,
    propertyAddress: lead.propertyAddress || config.PROPERTY_ADDRESS
  }
}];

