const data = $input.first().json;
const config = data.config;

const systemPrompt = `You are a professional real estate assistant.
Draft a warm personalized email proposing three 
viewing slots for a property to a prospective buyer.

The email should:
- Feel personally written by the agent — not automated
- Reference the lead name and property naturally
- Present three viewing options clearly and invitingly
- Encourage booking via the Calendly link provided
- Be professional but conversational
- Body maximum 3-4 sentences
- Never mention AI or automation

Format email_body as two parts separated by \\n\\n:
  Part 1: Greeting line only e.g. "Hi Sarah,"
  Part 2: Message body as one paragraph

Output ONLY valid JSON, no preamble, no markdown:
{
  "email_subject": "short friendly subject line",
  "email_body": "Hi {name},\\n\\nBody here.",
  "sms_message": "SMS under 160 chars"
}`;

const userPrompt = `Lead name: ${data.leadName}
Property: ${data.propertyAddress}
Agent name: ${config.AGENT_NAME}
Viewing options:
  Option 1: ${data.slot1}
  Option 2: ${data.slot2}
  Option 3: ${data.slot3}
Booking link: ${data.calendlyUrl}`;

return [{
  json: {
    ...data,
    anthropicBody: JSON.stringify({
      model: 'claude-haiku-4-5',
      max_tokens: 1000,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    })
  }
}];

// ============================================================
const SLOTS_NODE  = 'Generate Available Slots';
const CONFIG_NODE = 'Set: Agent Configuration';
// ============================================================

const slotsData = $(SLOTS_NODE).first().json;
const config    = $(CONFIG_NODE).first().json;
const allItems  = $input.all();

// Extract text from all three possible AI response formats
let rawText = '';
for (const item of allItems) {
  // Gemini format
  const gemini = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output || '';

  // OpenAI format
  const openai = item.json?.choices?.[0]?.message?.content || '';

  // Claude (HTTP Request) format
  const claude = item.json?.content?.[0]?.text || '';

  const text = gemini || openai || claude;
  if (text && text.includes('email_subject')) {
    rawText = text;
    break;
  }
}

const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

// Parse with fallback
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    email_subject: `Viewing request for ${slotsData.propertyAddress}`,
    email_body:    `Hi ${slotsData.leadName},\n\nThank you for your interest in ${slotsData.propertyAddress}. I have some great viewing slots available — please use the link below to book a time that suits you.`,
    sms_message:   `Hi ${slotsData.leadName}, viewing slots are ready for ${slotsData.propertyAddress}. Book here: ${slotsData.calendlyUrl}`
  };
}

// HTML email formatter
function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatEmailHtml(text) {
  if (!text) return '';
  return text.split(/\n\s*\n/)
    .map(p => `<p>${escapeHtml(p.trim())}</p>`)
    .join('');
}

// Build slots HTML for email
const slotsHtml = `
  <div style="background:#f8f9fa;border-radius:8px;padding:16px;margin:16px 0;">
    <p style="margin:0 0 8px 0;font-weight:bold;">📅 Available Viewing Slots:</p>
    <p style="margin:4px 0;">1️⃣ ${escapeHtml(slotsData.slot1)}</p>
    <p style="margin:4px 0;">2️⃣ ${escapeHtml(slotsData.slot2)}</p>
    <p style="margin:4px 0;">3️⃣ ${escapeHtml(slotsData.slot3)}</p>
  </div>
  <p>
    <a href="${escapeHtml(slotsData.calendlyUrl)}" 
       style="background:#27ae60;color:white;padding:12px 24px;
       border-radius:6px;text-decoration:none;font-weight:bold;">
      📅 Book Your Viewing →
    </a>
  </p>`;

// Build property details footer
const propertyHtml = `
  <hr style="border:none;border-top:1px solid #eee;margin:24px 0;">
  <p style="font-size:13px;color:#666;">
    <strong>Property:</strong> ${escapeHtml(slotsData.propertyAddress)}<br>
    ${config.PROPERTY_URL
      ? `<a href="${escapeHtml(config.PROPERTY_URL)}" style="color:#3498db;">View listing →</a>`
      : ''}
  </p>`;

// Full proposal email HTML
const proposalEmailHtml = `
  <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;color:#333;">
    ${formatEmailHtml(parsed.email_body)}
    ${slotsHtml}
    ${propertyHtml}
    <p style="font-size:12px;color:#999;margin-top:24px;">
      ${escapeHtml(config.AGENT_NAME)} | ${escapeHtml(config.AGENT_EMAIL)}
    </p>
  </div>`;

return [{
  json: {
    // Lead details
    leadName:        slotsData.leadName,
    leadEmail:       slotsData.leadEmail,
    leadPhone:       slotsData.leadPhone,
    propertyAddress: slotsData.propertyAddress,
    notes:           slotsData.notes,
    source:          slotsData.source,
    recordId:        slotsData.recordId,
    timestamp:       slotsData.timestamp,

    // Slots
    slot1:      slotsData.slot1,
    slot2:      slotsData.slot2,
    slot3:      slotsData.slot3,
    slot1Start: slotsData.slot1Start,
    slot2Start: slotsData.slot2Start,
    slot3Start: slotsData.slot3Start,
    calendlyUrl: slotsData.calendlyUrl,

    // AI output
    email_subject: parsed.email_subject,
    email_body:    parsed.email_body,
    sms_message:   parsed.sms_message,
    aiEngine:      config.AI_ENGINE,

    // Formatted email
    proposalEmailHtml,

    // Config passthrough
    config
  }
}];

const webhookData = $('Webhook: Calendly Booking Received').first().json;
const raw = webhookData;

// Handle all possible webhook wrapping structures
// n8n sometimes wraps POST body under $json.body
const root = raw.body || raw;

// Navigate to payload — handle both Calendly format and direct test payload
const payload  = root.payload  || root;
const event    = payload.event || {};
const invitee  = payload.invitee || {};
const eventType = payload.event_type || {};

// Debug — check what we actually received
console.log('root keys:', JSON.stringify(Object.keys(root)));
console.log('payload keys:', JSON.stringify(Object.keys(payload)));
console.log('event keys:', JSON.stringify(Object.keys(event)));
console.log('invitee keys:', JSON.stringify(Object.keys(invitee)));

// Parse viewing times
const startTime = event.start_time || null;
const endTime   = event.end_time   || null;

// Calculate reminder time — 24 hours before viewing
let reminderTime = null;
if (startTime) {
  const viewingDate = new Date(startTime);
  viewingDate.setHours(viewingDate.getHours() - 24);
  reminderTime = viewingDate.toISOString();
}

// Format viewing time for email display
const viewingDisplay = startTime
  ? new Date(startTime).toLocaleDateString('en-US', {
      weekday: 'long', year: 'numeric',
      month: 'long', day: 'numeric'
    }) + ' at ' +
    new Date(startTime).toLocaleTimeString('en-US', {
      hour: 'numeric', minute: '2-digit', hour12: true
    })
  : 'To be confirmed';

return [{
  json: {
    eventType:     eventType.name             || 'Property Viewing',
    eventUri:      event.uri                  || null,
    cancelUrl:     payload.cancel_url         || null,
    rescheduleUrl: payload.reschedule_url     || null,
    leadName:      invitee.name               || null,
    leadEmail:     invitee.email              || null,
    leadPhone:     invitee.text_reminder_number || null,
    viewingStart:  startTime,
    viewingEnd:    endTime,
    viewingDisplay,
    reminderTime,
    location:      event.location             || null,
    timestamp:     new Date().toISOString()
  }
}];

const data   = $input.first().json;
const config = $('Set: Agent Configuration (Phase 2)').first().json;

// Clean date format — strip microseconds
const cleanStart = data.viewingStart.replace(/(\.\d{3})\d+Z$/, '$1Z');
const cleanEnd   = data.viewingEnd.replace(/(\.\d{3})\d+Z$/, '$1Z');

const eventBody = {
  summary:     `Property Viewing - ${data.leadName}`,
  location:    config.PROPERTY_ADDRESS,
  description: `Lead: ${data.leadName}\nEmail: ${data.leadEmail}\nPhone: ${data.leadPhone || 'Not provided'}\nProperty: ${config.PROPERTY_ADDRESS}\nCancel: ${data.cancelUrl}\nReschedule: ${data.rescheduleUrl}`,
  start: {
    dateTime: cleanStart,
    timeZone: 'UTC'
  },
  end: {
    dateTime: cleanEnd,
    timeZone: 'UTC'
  },
  attendees: [
    { email: data.leadEmail },
    { email: config.AGENT_EMAIL }
  ],
  sendUpdates: 'all'
};

return [{
  json: {
    ...data,
    eventBodyJson: JSON.stringify(eventBody)
  }
}];
